const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const devId = flow.get('deviceId') || 'cronusfarm-01';
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
let key = (msg.topic || '').toString().trim();
if (!key && msg.properties && msg.properties.topic) key = String(msg.properties.topic).trim();
if (!key) {
  node.warn('KV: topic 없음 — Change 노드·슬라이더 설정 확인');
  return null;
}
msg.method = 'POST';
msg.url = base + '/settings/kv';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: devId,
  key,
  value: String(msg.payload)
});
return msg;

const d = new Date();
msg.payload = d.toLocaleString('ko-KR', { hour12: false });
return msg;

const s = (msg.payload || '').toString();
const parts = s.split('|').map(x => x.trim());
const w = parts.find(x => x.startsWith('W:'));
let ssid = '-';
let ip = '-';
if (w) {
  const rest = w.slice(2).trim();
  const k = rest.lastIndexOf(' ip=');
  if (k >= 0 && rest.startsWith('ssid=')) {
    ssid = rest.slice(5, k).trim();
    ip = rest.slice(k + 4).trim();
    if (!ssid) ssid = '-';
    if (!ip) ip = '-';
    if (ip === '0.0.0.0') ip = '-';
  }
}
return [[{ payload: ssid }], [{ payload: ip }]];

const s=(msg.payload||'').toString().trim();
msg.payload = (s.split(/\s+/)[0]||'-');
return msg;

const s=(msg.payload||'').toString().trim();
msg._ok = (s==='active');
msg.payload = msg._ok ? 'online' : 'offline';
return msg;

const s=(msg.payload||'').toString().trim();
msg._ok = (s==='active');
msg.payload = msg._ok ? 'online' : 'offline';
return msg;

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
else if (p != null && typeof p !== 'string') p = String(p);
else p = (p || '').toString();
flow.set('arduinoLastStatusMs', Date.now());
flow.set('lastStatusStr', p.trim());
msg.payload = p;
return msg;

let p = msg.payload;
if (Buffer.isBuffer(p)) p = p.toString('utf8');
else if (p != null && typeof p !== 'string') p = String(p);
flow.set('arduinoLastTeleMs', Date.now());
flow.set('lastTeleStr', (p || '').toString());
msg.payload = p;
return msg;

// 문자열 payload만 (§2.2). G: 는 끝 구간 — SSID에 '|' 가 있으면 split('|') 실패 → 정규식 추출
const s = (flow.get('lastTeleStr') || '').toString();
let line = '— (tele 수신 대기)';
if (s.trim().length) {
  let raw = '';
  const m = s.match(/\|\s*G:\s*(.+)$/);
  if (m && m[1] !== undefined) {
    raw = m[1].trim();
  }
  if (!raw.length) {
    const ps = s.split('|').map(x => String(x).trim());
    const pG = ps.find(x => /^g:/i.test(x));
    if (pG) raw = pG.replace(/^g:\s*/i, '').trim();
  }
  if (!raw.length) {
    line = '— (G: 없음 — R4에 최신 스케치 업로드 또는 tele 끝에 | G:… 없음)';
    flow.set('lastTeleG', '');
    flow.set('lastTeleGWarn', false);
  } else {
    line = raw;
    flow.set('lastTeleG', line);
    flow.set('lastTeleGWarn', line !== 'ok');
  }
} else {
  flow.set('lastTeleG', '');
  flow.set('lastTeleGWarn', false);
}
msg.payload = line;
return msg;

const now=Date.now();
const ls=flow.get('arduinoLastStatusMs')||0;
const lt=flow.get('arduinoLastTeleMs')||0;
const TELE_MS=15000;
const teleOk = lt > 0 && (now - lt) < TELE_MS;

function normStatus(v) {
  let s = (v === undefined || v === null) ? '' : v;
  if (Buffer.isBuffer(s)) s = s.toString('utf8');
  s = String(s).replace(/^\uFEFF/, '').trim().replace(/^['"]+|['"]+$/g, '');
  return s;
}
let retain = normStatus(flow.get('lastStatusStr'));
let rl = retain.toLowerCase();
if (rl.charAt(0) === '{') {
  try {
    const o = JSON.parse(retain);
    if (o && typeof o.state === 'string') {
      retain = normStatus(o.state);
      rl = retain.toLowerCase();
    }
  } catch (e) { /* 무시 */ }
}
const retainOn = (rl === 'online');
const retainOff = (rl === 'offline');
let connOk = false;
if (retainOff) connOk = false;
else if (retainOn) connOk = true;
else if (retain) connOk = teleOk;
else connOk = teleOk;

msg._ok = teleOk;
msg._connOk = connOk;
msg.connLineOk = !!connOk;
msg.statusAge = ls ? Math.floor((now - ls) / 1000) : null;
msg.teleAge = lt ? Math.floor((now - lt) / 1000) : null;
msg.statusRetain = retain;
const raw = (flow.get('lastTeleStr') || '').toString();
msg.telePreview = raw;
msg.payload = raw;
return msg;

// tele 예)
// S:led_a1=0 ... pump_b2=1 fan_a1=1 | A:led_a1=0 ... auto_fan_a1=0 | T:pump_a1=30/90 ...
//
// 중요: tele이 1초마다 오기 때문에, UI 드롭다운(dd_*)을 매번 덮어쓰면 "시간이 계속 바뀌는" 것처럼 보일 수 있습니다.
// 여기서는 on_/off_ 초 값만 반영하고(dd_ 분/초 UI 갱신은 하지 않음), 드롭다운은 사용자가 바꾼 값이 유지되도록 합니다.

const s=(msg.payload||'').toString();
function parseKV(part){
  const out={};
  (part||'').trim().split(/\s+/).forEach(tok=>{
    const m=tok.match(/^([^=]+)=(.+)$/);
    if(!m) return;
    out[m[1]] = m[2];
  });
  return out;
}

const ps = s.split('|').map(x=>x.trim());
const pS = ps.find(x=>x.startsWith('S:'));
const pA = ps.find(x=>x.startsWith('A:'));
const pT = ps.find(x=>x.startsWith('T:'));

const kvS = parseKV(pS ? pS.slice(2) : '');
const kvA = parseKV(pA ? pA.slice(2) : '');
const kvT = parseKV(pT ? pT.slice(2) : '');

const chKeys = ['led_a1','led_a2','pump_a1','pump_a2','led_b1','pump_b1','pump_b2','fan_a1','fan_a2','fan_b1','fan_b2','pump_c1','pump_c2','pump_d1','pump_d2'];

const out=[];
chKeys.forEach(k=>{
  if(k in kvS) {
    const v = (kvS[k]==='1')?1:0;
    flow.set(k, v);
    out.push({topic:k, payload: v});
  }
});
chKeys.forEach(k=>{
  const ak = 'auto_'+k;
  if(k in kvA) {
    const v = (kvA[k]==='1')?1:0;
    flow.set(ak, v);
    out.push({topic:ak, payload: v});
  }
});

Object.keys(kvT).forEach(k=>{
  // pump_x=30/90
  const m = (kvT[k]||'').match(/^(\d+)\/(\d+)$/);
  if(!m) return;
  const onV = parseInt(m[1],10);
  const offV = parseInt(m[2],10);
  const onK = 'on_'+k;
  const offK = 'off_'+k;
  flow.set(onK, onV);
  flow.set(offK, offV);
  out.push({topic:onK, payload: onV});
  out.push({topic:offK, payload: offV});
});

return [out];

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

const k = (msg.topic||'').toString().trim();
if(!k) return null;
const v = (msg.payload===1 || msg.payload===true || msg.payload==='1' || msg.payload==='on') ? 1 : 0;

// 스위치 조작 시: 해당 채널을 수동(auto=0)으로 고정하고, 즉시 ON/OFF 값을 cmd로 발행
// - 출력 1개에서 연속 두 MQTT 메시지: [m1, m2] 반환. [[m1,m2]]는 잘못된 형태입니다.
const t = `cronusfarm/${devId}/cmd`;
const m1 = {topic:t, payload:`auto_${k}=0`};
const m2 = {topic:t, payload:`${k}=${v}`};
return [m1, m2];

const key = (msg.topic || '').toString();
const v = Number(msg.payload);
if (!key) return null;
flow.set(key, isNaN(v) ? 0 : v);
const mm = key.match(/^dd_(on|off)_(pump_[a-z0-9]+)_(m|s)$/);
if (!mm) return null;
const kind = mm[1];
const pk = mm[2];
const minutes = Number(flow.get('dd_' + kind + '_' + pk + '_m')) || 0;
const seconds = Number(flow.get('dd_' + kind + '_' + pk + '_s')) || 0;
let t = minutes * 60 + seconds;
if (t < 1) t = 1;
if (t > 3600) t = 3600;
const outTopic = kind + '_' + pk;
flow.set(outTopic, t);
msg.topic = outTopic;
msg.payload = t;
return msg;

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

const key = (msg.topic||'').toString();
const val = msg.payload;
if (key) flow.set(key, val);

const keys = [
  'led_a1','led_a2','pump_a1','pump_a2','led_b1','pump_b1','pump_b2',
  'auto_led_a1','auto_led_a2','auto_pump_a1','auto_pump_a2','auto_led_b1','auto_pump_b1','auto_pump_b2',
  'on_pump_a1','off_pump_a1','on_pump_a2','off_pump_a2','on_pump_b1','off_pump_b1','on_pump_b2','off_pump_b2'
];

const parts=[];
keys.forEach(k=>{
  const v = flow.get(k);
  if (v === undefined || v === null) return;
  parts.push(`${k}=${v}`);
});

msg.topic = `cronusfarm/${devId}/cmd`;
msg.payload = parts.join(' ');
return msg;

function fmtKmaObsLabel(o) {
  if (!o || typeof o !== 'object') return '';
  const d = String(o.base_date || '').trim();
  let t = String(o.base_time != null ? o.base_time : '').trim();
  if (d.length < 8) return '';
  if (!t) t = '0000';
  t = t.padStart(4, '0');
  const y = d.slice(0, 4);
  const mo = d.slice(4, 6);
  const da = d.slice(6, 8);
  const hh = t.slice(0, 2);
  const mm = t.slice(2, 4);
  return y + '.' + mo + '.' + da + ' ' + hh + ':' + mm + ' KST';
}
let p = msg.payload;
if (typeof p === 'string') {
  try { p = JSON.parse(p); } catch (e) { return msg; }
}
if (p && typeof p === 'object') {
  p.kma_obs_label = fmtKmaObsLabel(p);
  flow.set('kmaSnapshot', p);
  global.set('kmaSnapshot', p);
  flow.set('kmaSnapshotTs', Date.now());
  global.set('kmaSnapshotTs', Date.now());
}
msg.payload = p;
return msg;

const devId = flow.get('deviceId') || 'cronusfarm-01';
flow.set('deviceId', devId);

// FlexDash 위젯마다 topic이 다르게 들어올 수 있어 방어적으로 처리
const candidates = [
  msg.topic,
  msg.fd_output_topic,
  msg.fdOutputTopic,
  msg?._fd?.output_topic,
  msg?._fd?.outputTopic,
  msg?.widget?.topic
];
const k = (candidates.find(x => (x ?? '').toString().trim().length > 0) ?? '').toString().trim();
if(!k) return null;

// FlexDash toggle payload는 기본 true/false 또는 1/0
const v = (msg.payload===1 || msg.payload===true || msg.payload==='1' || msg.payload==='on') ? 1 : 0;

const t = `cronusfarm/${devId}/cmd`;
const m1 = {topic:t, payload:`auto_${k}=0`};
const m2 = {topic:t, payload:`${k}=${v}`};
return [m1, m2];

const d = msg.device || 'unknown';
const p = msg.payload || {};
const out = [];
if (p.ph   !== undefined) out.push({ topic: `${d}:pH`,   payload: p.ph });
if (p.ec   !== undefined) out.push({ topic: `${d}:EC`,   payload: p.ec });
if (p.temp !== undefined) out.push({ topic: `${d}:Temp`, payload: p.temp });
return [out];

// PH-W3988 (Tuya dgnbj, proto 3.5) — DP from tuya-local #555/#562 + IoT shadow
// 8 temp°C×10, 102 pH×100, 107 TDS ppm, 110 EC µS/cm, 113 salinity ppm, 116 S.G×1000, 119 ORP mV (optional)
const DEVICE = 'cronus';
const MAP = {
  temp: { dp: '8', scale: 10 },
  ph:   { dp: '102', scale: 100 },
  tds:  { dp: '107', scale: 1 },
  ec:   { dp: '110', scale: 1 },
  salt: { dp: '113', scale: 1 },
  sg:   { dp: '116', scale: 1000 }
};

let src = null;
const p = msg.payload;
if (p && typeof p === 'object') {
  if (p.dps && typeof p.dps === 'object') src = p.dps;
  else if (p.data && p.data.dps && typeof p.data.dps === 'object') src = p.data.dps;
  else if (Object.keys(p).every(k => /^\d+$/.test(k))) src = p;
}
if (!src || typeof src !== 'object') return null;

const norm = {};
for (const [k, v] of Object.entries(src)) norm[String(k)] = v;
src = norm;

const parsed = { ts: new Date().toISOString() };
for (const [k, cfg] of Object.entries(MAP)) {
  const raw = src[cfg.dp];
  if (raw === undefined || raw === null) continue;
  const v = Number(raw) / cfg.scale;
  if (Number.isFinite(v)) parsed[k] = Math.round(v * 1000) / 1000;
}

const key = 'last_' + DEVICE;
const last = flow.get(key) || {};
const merged = Object.assign({}, last, parsed);
flow.set(key, merged);
msg.payload = merged;
msg.device = DEVICE;
return msg;

const p = msg.payload || {};
let obj = p;
if (typeof obj === 'string') {
  try { obj = JSON.parse(obj); } catch (e) { return null; }
}
if (!obj || typeof obj !== 'object') return null;
const out = { ph: obj.ph, ec: obj.ec, temp: obj.temp };
if (out.ph === undefined && out.ec === undefined && out.temp === undefined) return null;
msg.topic = 'cronus/water';
msg.payload = JSON.stringify(out);
return msg;

const dis = (env.get('CRONUSFARM_SQLITE_DISABLE') || '').toString().trim();
if (dis === '1' || dis.toLowerCase() === 'true') return null;
const p = msg.payload || {};
const minMs = parseInt((env.get('CRONUSFARM_PHW_SQLITE_MIN_MS') || '30000').toString(), 10) || 30000;
const now = Date.now();
const last = flow.get('lastPhwSensorMs') || 0;
if (now - last < minMs) return null;
flow.set('lastPhwSensorMs', now);
const base = (env.get('CRONUSFARM_SQLITE_BRIDGE_URL') || 'http://127.0.0.1:18766').toString().replace(/\/$/, '');
msg.method = 'POST';
msg.url = base + '/ingest/sensor';
msg.headers = { 'Content-Type': 'application/json; charset=utf-8' };
msg.payload = JSON.stringify({
  device_id: 'cronusfarm-01',
  zone: 'phw3988',
  ph: p.ph,
  ec: p.ec,
  temp_c: p.temp,
  source: 'phw3988',
  raw_json: JSON.stringify(p),
  ts_ms: now
});
return msg;
